INSERT INTO `categories` VALUES (1,'Manga','manga','Truyện tranh Nhật Bản (thường đọc từ phải sang trái).'),(2,'Manhwa','manhwa','Truyện tranh Hàn Quốc (webtoon, cuộn dọc, in màu).'),(3,'Manhua','manhua','Truyện tranh Trung Quốc.'),(4,'Comic','comic','Truyện tranh Âu Mỹ.'),(5,'Shounen','shounen','Truyện hướng tới nam thiếu niên (nhiều hành động, tình bạn).'),(6,'Shoujo','shoujo','Truyện hướng tới nữ thiếu niên (nhẹ nhàng, lãng mạn).'),(7,'Seinen','seinen','Truyện hướng tới nam thanh niên (nội dung trưởng thành, dark, tâm lý).'),(8,'Josei','josei','Truyện hướng tới nữ trưởng thành (tình cảm thực tế, đời sống).'),(9,'Hành Động','hanh-dong','Các pha đánh nhau, bạo lực, võ thuật.'),(10,'Lãng Mạn','lang-man','Tập trung vào tình yêu đôi lứa (Ngôn tình).'),(11,'Hài Hước','hai-huoc','Tình huống gây cười, giải trí.'),(12,'Kịch Tính','kich-tinh','Xung đột tâm lý, bi kịch, plot twist căng thẳng.'),(13,'Viễn Tưởng','vien-tuong','Phép thuật, thế giới thần tiên, quái vật.'),(14,'Khoa Học Viễn Tưởng','khoa-hoc-vien-tuong','Tương lai, công nghệ cao, du hành vũ trụ.'),(15,'Kinh Dị','kinh-di','Đáng sợ, ma quỷ, máu me.'),(16,'Bí Ẩn','bi-an','Trinh thám, giải đố, hồi hộp.'),(17,'Đời Thường','doi-thuong','Nhẹ nhàng, lát cắt cuộc sống hàng ngày.'),(18,'Thể Thao','the-thao','Bóng đá, bóng rổ, đua xe, e-sports.'),(19,'Đam Mỹ','dam-my','Tình cảm nam x nam (Yaoi / BoyLove).'),(20,'Bách Hợp','bach-hop','Tình cảm nữ x nữ (Yuri / GirlLove).');
/*!40000 ALTER TABLE `categories` ENABLE KEYS */;
UNLOCK TABLES;

