INSERT INTO `comics` VALUES (7,'Yankee-Kun To Kagaku Gohan',NULL,'yankee-kun-to-kagaku-gohan','Đang cập nhật','https://img.otruyenapi.com/uploads/comics/yankee-kun-to-kagaku-gohan-thumb.jpg','scraped_yankee-kun-to-kagaku-gohan','Yankee-Kun To Kagaku Gohan - Yankee - kun To Kagaku Gohan',1,0,5,0,'2026-03-30 07:57:42','2026-03-30 11:47:16',NULL),(8,'Xin Hãy Chăm Sóc Nhiều Hơn',NULL,'xin-hay-cham-soc-nhieu-hon','Đang cập nhật','https://img.otruyenapi.com/uploads/comics/xin-hay-cham-soc-nhieu-hon-thumb.jpg','scraped_xin-hay-cham-soc-nhieu-hon','Cứu mạng, sao xem mắt lại gặp được “bạn trai cũ”?',1,0,5,0,'2026-03-30 07:57:46','2026-03-30 07:57:46',NULL),(9,'Vòng Chơi Thứ Hai Của Chiến Binh Cuồng Nộ',NULL,'vong-choi-thu-hai-cua-chien-binh-cuong-no','Đang cập nhật','https://img.otruyenapi.com/uploads/comics/vong-choi-thu-hai-cua-chien-binh-cuong-no-thumb.jpg','scraped_vong-choi-thu-hai-cua-chien-binh-cuong-no','Truyện tranh Vòng Chơi Thứ Hai Của Chiến Binh Cuồng Nộ được cập nhật nhanh và đầy đủ nhất tại TruyenQQ. Bạn đọc đừng quên để lại bình luận và chia sẻ, ủng hộ TruyenQQ ra các chương mới nhất của truyện Vòng Chơi Thứ Hai Của Chiến Binh Cuồng Nộ.',1,0,5,0,'2026-03-30 07:57:49','2026-03-30 11:47:16',NULL),(10,'Vạn Cổ Tối Cường Tông',NULL,'van-co-toi-cuong-tong','Đang cập nhật','https://img.otruyenapi.com/uploads/comics/van-co-toi-cuong-tong-thumb.jpg','scraped_van-co-toi-cuong-tong','Truyện tranh Vạn Cổ Tối Cường Tông được cập nhật nhanh và đầy đủ nhất tại . Bạn đọc đừng quên để lại bình luận và chia sẻ, ủng hộ ra các chương mới nhất của truyện Vạn Cổ Tối Cường Tông.',1,0,5,0,'2026-03-30 07:57:56','2026-03-30 11:47:16',NULL),(11,'Ứng Dụng Thần Kỳ',NULL,'ung-dung-than-ky','Đang cập nhật','https://img.otruyenapi.com/uploads/comics/ung-dung-than-ky-thumb.jpg','scraped_ung-dung-than-ky','Tất cả mọi người đều coi thường Vương Tiểu Bình vì vết thương ở chân. Tuy nhiên, anh vô tình một ứng dụng di động. Điều kì lạ là các chỉ số trong ứng dụng đều trở thành hiện thực',1,0,5,0,'2026-03-30 07:57:59','2026-03-30 07:57:59',NULL),(12,'Ta Trời Sinh Đã Là Nhân Vật Phản Diện Ngoại Truyện',NULL,'ta-tr-i-sinh-l-nh-n-v-t-ph-n-di-n-ngo-i-truy-n','Đang cập nhật','https://img.otruyenapi.com/uploads/comics/ta-troi-sinh-da-la-nhan-vat-phan-dien-ngoai-truyen-thumb.jpg','scraped_ta-tr-i-sinh-l-nh-n-v-t-ph-n-di-n-ngo-i-truy-n','Ngoại Truyện PremiumPremium',1,0,5,0,'2026-03-30 09:27:36','2026-03-30 11:47:16',NULL),(13,'Unemployed Gye Baeksun',NULL,'unemployed-gye-baeksun','Đang cập nhật','https://img.otruyenapi.com/uploads/comics/unemployed-gye-baeksun-thumb.jpg','scraped_unemployed-gye-baeksun','Unemployed Gye Baeksun - Unemployed Gye Baeksun',1,0,5,1,'2026-03-30 09:29:15','2026-03-30 11:47:16',NULL),(14,'Đấu La Đại Lục 5',NULL,'-u-la-i-l-c-5','Đang cập nhật','https://img.otruyenapi.com/uploads/comics/dau-la-dai-luc-5-thumb.jpg','scraped_-u-la-i-l-c-5','Nhất đại Thần Vương trùng sinh tại đôi này nhân loại cũng không hữu hảo yêu tinh trong đại lục, có thể hay không một lần nữa truy hồi thê tử. Thiên hình vạn trạng Yêu Thần biến lại sẽ mang lại cho hắn như thế nào trùng sinh chi đường? Đều ở nhất đại Thần Vương hành trình tìm vợ, Đấu La Đại Lục Bộ 5:, trùng sinh Đường Tam!\n[GHI CHÚ: Chỉ import 10 chapter demo do cài đặt hệ thống Admin]',1,59450,3.82208,0,'2026-03-30 11:25:28','2026-03-30 11:25:28',626),(15,'Đảo Hải Tặc',NULL,'-o-h-i-t-c','Oda Eiichiro','https://img.otruyenapi.com/uploads/comics/dao-hai-tac-thumb.jpg','scraped_-o-h-i-t-c','One Piece xoay quanh 1 nhóm cướp biển được gọi là Băng Hải tặc Mũ Rơm - Straw Hat Pirates - được thành lập và lãnh đạo bởi thuyền trưởng Monkey D. Luffy. Cậu bé Luffy có ước mơ tìm thấy kho báu vĩ đại nhất, One Piece, của Vua Hải Tặc đời trước Gold D. Roger và trở thành Vua Hải Tặc đời kế tiếp. Ở Việt Nam hiện nay, truyện đang được Nhà xuất bản Thanh Hóa xuất bản nhưng không có bản quyền, với tên gọi là Đảo Hải tặc Cốt truyện: Monkey D. Luffy, 1 cậu bé rất thích hải tặc có ước mơ tìm được kho báu One Piece và trở thành Vua hải tặc - Pirate King. Lúc nhỏ, Luffy tình cờ ăn phải trái quỉ (Devil Fruit) Gomu Gomu, nó cho cơ thể cậu khả năng co dãn đàn hồi như cao su nhưng đổi lại cậu sẽ không bao giờ biết bơi. Sau đó Luffy lại được Shank cứu thoát tuy nhiên ông ta bị mất 1 cánh tay. Sau đấy Shank chia tay Luffy và để lại cho cậu cái mũ rơm (Straw Hat) và nói rằng: \"Sau này bao giờ thành cướp biển hãy gặp ta và trả lại nó\". Chính lời nói này đã thúc đầy Luffy trở thành 1 cướp biển thật sự.',1,98149,3.55077,0,'2026-03-30 11:57:10','2026-03-30 11:57:10',2738),(16,'Tousan wa [Kensei], Kaasan wa [Kenshin], Boku wa [Ochi〇po Chanbara Master]',NULL,'tousan-wa-kensei-kaasan-wa-kenshin-boku-wa-ochi-po-chanbara-master-','Tokiwa Yosyo','https://uploads.mangadex.org/covers/b5361588-0194-462a-9dda-778ba3e32a04/1a72c5ad-3f61-4cc8-87d7-aabd44fc3807.jpg.512.jpg','scraped_tousan-wa-kensei-kaasan-wa-kenshin-boku-wa-ochi-po-chanbara-master-','In this world you’re granted a \"Job\" from the heavens upon turning 14.\nIt’s a crucial element that determines a person’s talent, their role in the world, and their life and destiny.\nBorn to a father who is the [Sword Saint] and a mother who is the [Sword God], the \"Job\" Regulus was granted is—[P*nis-Sword Dueling Master]!!\nA swordsman’s tale unlike anything you’ve ever seen begins!!',1,20846,4.42797,1,'2026-03-30 12:38:29','2026-03-30 12:38:29',4061),(17,'Hiota no Kanojo ga Ore no Motteru Eroge ni Kyoumi Shinshin Nanda ga......',NULL,'hiota-no-kanojo-ga-ore-no-motteru-eroge-ni-kyoumi-shinshin-nanda-ga-','Takizawa Kei','https://uploads.mangadex.org/covers/d05470ae-e0b2-4f74-8e71-0fbc68565cd8/a8e3f95c-baf4-4815-a0bb-4da5628d0716.jpg.512.jpg','scraped_hiota-no-kanojo-ga-ore-no-motteru-eroge-ni-kyoumi-shinshin-nanda-ga-','Kazuma, a highschool student who loves eroge, has been confessed to by the honour student and beautiful girl, Misaki Honoka, who\'s the school\'s prodigy. What\'s more, Honoka had declared that she would try her best to become a \"heroine\" that Kazuma likes?! \"Can you… train me?\" What kind of eroge is this?',1,26378,3.81353,1,'2026-03-30 12:39:32','2026-03-30 12:39:32',2601),(19,'Set-up - HentaiVN',NULL,'set-up-hentaivn','Đang cập nhật','https://dcnvn2.mbpro.vip/images/covers/227d74f9-0b10-46e5-9a6c-62cc17ba380867c3e7c346d8b.png','scraped_set-up-hentaivn','Không có thông tin nội dung.',1,59258,4.76588,1,'2026-03-30 17:59:51','2026-03-30 17:59:51',3540),(29,'Tân Thế Giới Tuyệt Vời - HentaiVN',NULL,'t-n-th-gi-i-tuy-t-v-i-hentaivn','Đang cập nhật','https://dcnvn2.mbpro.vip/images/covers/truyen-tan-the-gioi-tuyet-voi-001.jpg','scraped_t-n-th-gi-i-tuy-t-v-i-hentaivn','Không có thông tin nội dung.',1,81991,4.2244,1,'2026-03-31 03:34:39','2026-03-31 03:34:39',3085),(30,'Ong Chúa - HentaiVN',NULL,'ong-ch-a-hentaivn','Đang cập nhật','https://dcnvn2.mbpro.vip/images/covers/truyen-ong-chua.jpg','scraped_ong-ch-a-hentaivn','Không có thông tin nội dung.',1,74956,4.89633,1,'2026-03-31 04:10:19','2026-03-31 04:10:19',1394);
